package com.argument.adjudication;

import com.argument.common.exception.*;
import com.argument.integration.UnifiedVersionIdentity;
import com.argument.version.*;
import com.argument.version.port.AnnotationDependencies;
import com.argument.version.port.VersionIdentity.Actor;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.*;
import static com.argument.adjudication.AdjudicationService.*;

/** B's query/custom/expert workflows adapted to the one shared session and immutable sources. */
@Service
public class ReviewWorkflowService {
    private final AdjudicationService adjud;private final AdjudicationRepository store;private final VersionRepository versions;private final AnnotationDependencies data;private final ObjectMapper mapper;private final JdbcTemplate jdbc;private final ReviewCommandValidator validator;private final UnifiedVersionIdentity identity;
    public ReviewWorkflowService(AdjudicationService adjud,AdjudicationRepository store,VersionRepository versions,AnnotationDependencies data,ObjectMapper mapper,JdbcTemplate jdbc,ReviewCommandValidator validator,UnifiedVersionIdentity identity){this.adjud=adjud;this.store=store;this.versions=versions;this.data=data;this.mapper=mapper;this.jdbc=jdbc;this.validator=validator;this.identity=identity;}
    private void insert(String kind,ObjectNode n){jdbc.update("INSERT INTO workflow_records VALUES(?,?,?)",kind,n.path("id").asText(),n.toString());}
    private void match(ObjectNode n,int expected){if(n.path("recordVersion").asInt()!=expected)throw new VersionFailure(ErrorCode.VERSION_CONFLICT,"记录已变化，请刷新后重试",Map.of("objectId",n.path("id").asText(),"currentRecordVersion",n.path("recordVersion").asInt()));}
    private ObjectNode replay(Actor actor,String op,String key,ObjectNode body){return versions.receipt(actor.id(),op,VersionJson.uuid(key),VersionJson.canonicalHash(body));}
    private void receipt(Actor actor,String op,String key,ObjectNode body,ObjectNode response,ObjectNode before,ObjectNode after){versions.receipt(actor.id(),op,key,VersionJson.canonicalHash(body),response,before,after,body.path("reason").asText(body.path("question").asText()));}
    private ObjectNode arbiter(Actor actor,String id){var w=adjud.workspace(actor,VersionJson.uuid(id));return (ObjectNode)w.get("session");}
    private ObjectNode item(ObjectNode session,String kind,String id){require(Set.of("PROPOSITION","RELATION").contains(kind),ErrorCode.VALIDATION_ERROR,"裁定项类型错误");var item=store.item(VersionJson.uuid(id),kind);require(item.path("sessionId").equals(session.path("id")),ErrorCode.FORBIDDEN,"裁定项不属于本会话");return item;}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public ObjectNode propositions(Actor actor,String id,String status,String conflict){var session=arbiter(actor,id);if(status!=null)require(Set.of("OPEN","DECIDED","ESCALATED","RETURNED").contains(status),ErrorCode.VALIDATION_ERROR,"未知项目状态");var result=mapper.createObjectNode();result.set("session",session);var items=result.putArray("items");for(var i:store.items(id,"PROPOSITION"))if((status==null||status.equals(i.path("status").asText()))&&(conflict==null||conflict.equals(i.path("conflictType").asText()))){var v=items.addObject();v.set("item",i);var groups=v.putArray("candidates");for(var snapshot:adjud.snapshots(session)){var g=groups.addObject();g.set("versionId",snapshot.path("version").get("id"));g.set("displayCode",snapshot.path("version").get("displayCode"));var es=g.putArray("elements");for(var e:snapshot.path("elements"))if(contains(i.path("candidateElementIds"),e.path("id").asText()))es.add(e);}var decision=store.decisions(id).stream().filter(d->d.path("id").equals(i.path("decisionId"))).findFirst();if(decision.isPresent())v.set("currentDecision",decision.get());else v.putNull("currentDecision");}return result;}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public ObjectNode context(Actor actor,String id,String kind,String itemId){var w=adjud.workspace(actor,id);var s=(ObjectNode)w.get("session");var i=item(s,kind,itemId);var result=mapper.createObjectNode();result.set("session",s);result.put("itemKind",kind);result.set("item",i);var vs=result.putArray("sourceVersions");var es=result.putArray("candidateElements");var rs=result.putArray("candidateRelations");var ps=result.putArray("candidateParticipants");for(var source:adjud.snapshots(s)){vs.add(source.path("version"));for(var e:source.path("elements"))if("PROPOSITION".equals(kind)&&contains(i.path("candidateElementIds"),e.path("id").asText()))es.add(e);if("RELATION".equals(kind)){for(var r:source.path("relations"))if(contains(i.path("candidateRelationIds"),r.path("id").asText()))rs.add(r);for(var p:source.path("participants"))if(contains(i.path("candidateRelationIds"),p.path("relationId").asText()))ps.add(p);}}
        for(String f:List.of("documentTextVersion","annotationScope","guideVersion"))result.set(f,w.get(f));var allowed=result.putArray("allowedActions");if("PROPOSITION".equals(kind)&&"PROPOSITION_REVIEW".equals(s.path("status").asText())&&Set.of("OPEN","DECIDED").contains(i.path("status").asText()))allowed.add("CUSTOM");return result;}
    @Transactional
    public ObjectNode saveCustom(Actor actor,String id,String key,ObjectNode body){validator.validate("J10",body);var s=adjud.locked(actor,id);var i=item(s,body.path("itemKind").asText(),body.path("itemId").asText());String op="J10:"+id;var cached=replay(actor,op,key,body);if(cached!=null)return cached;require("PROPOSITION".equals(body.path("itemKind").asText())&&body.path("customRelations").isEmpty(),ErrorCode.INVALID_CUSTOM_GRAPH,"本批只接命题自定义，关系自定义在下一阶段接入");require("PROPOSITION_REVIEW".equals(s.path("status").asText())&&Set.of("OPEN","DECIDED").contains(i.path("status").asText()),ErrorCode.INVALID_REVIEW_STATE,"自定义项当前不可编辑");require(!body.path("reason").asText().isBlank(),ErrorCode.VALIDATION_ERROR,"请填写补正理由");
        // One-to-one is expressible by the current frozen mapping. Never silently select a split/merge endpoint.
        require(body.path("customElements").size()==1,ErrorCode.INVALID_CUSTOM_GRAPH,"拆分合并需先确认 M13；当前只支持一对一补正");var input=body.path("customElements").get(0);var ctx=context(actor,id,"PROPOSITION",i.path("id").asText());var candidates=ctx.path("candidateElements");require(!candidates.isEmpty(),ErrorCode.SOURCE_INCOMPLETE,"候选来源为空");var sources=new HashSet<String>();var sourceOwners=new HashSet<String>();for(var e:candidates){sources.add(e.path("id").asText());require(sourceOwners.add(e.path("ownerId").asText()),ErrorCode.INVALID_CUSTOM_GRAPH,"当前项为一对多，需正式映射模型");require(e.path("startOffset").equals(input.path("startOffset"))&&e.path("endOffset").equals(input.path("endOffset")),ErrorCode.INVALID_CUSTOM_GRAPH,"本批不能偏离统一边界");}var selected=new HashSet<String>();for(var source:input.path("sourceElementIds"))require(sources.contains(source.asText())&&selected.add(source.asText()),ErrorCode.INVALID_CUSTOM_GRAPH,"来源要素越出当前项或重复");require(!selected.isEmpty(),ErrorCode.INVALID_CUSTOM_GRAPH,"自定义结果需要明确原始来源");String guide=ctx.path("guideVersion").path("id").asText();var labels=data.find("label","guideVersionId",guide).stream().filter(l->l.path("code").equals(input.path("labelCode"))).toList();require(labels.size()==1&&!"GM-C".equals(input.path("labelCode").asText()),ErrorCode.VALIDATION_ERROR,"标签不属于当前绑定指南");var label=labels.get(0);String text=ctx.path("documentTextVersion").path("normalizedText").asText();int start=input.path("startOffset").asInt(),end=input.path("endOffset").asInt();require(start>=0&&end>start&&end<=text.length()&&!(start>0&&Character.isLowSurrogate(text.charAt(start))&&Character.isHighSurrogate(text.charAt(start-1)))&&!(end<text.length()&&Character.isLowSurrogate(text.charAt(end))&&Character.isHighSurrogate(text.charAt(end-1))),ErrorCode.OFFSET_INVALID,"原文边界错误");
        var annotation=mapper.createObjectNode();VersionJson.stamp(annotation,actor.id(),VersionJson.now());annotation.put("sessionId",id).put("itemKind","PROPOSITION").put("itemId",i.path("id").asText()).put("reason",body.path("reason").asText().trim());annotation.putArray("relationIds");var e=mapper.createObjectNode();VersionJson.stamp(e,actor.id(),VersionJson.now());e.put("ownerType","ARBITER_CUSTOM").put("ownerId",annotation.path("id").asText());e.set("documentTextVersionId",candidates.get(0).get("documentTextVersionId"));e.set("annotationScopeId",candidates.get(0).get("annotationScopeId"));e.put("startOffset",start).put("endOffset",end).put("text",text.substring(start,end));e.set("labelDefinitionId",label.get("id"));e.set("labelCode",label.get("code"));e.put("isProposition","PROPOSITION".equals(label.path("category").asText()));e.putNull("displayNo");e.set("sourceElementIds",input.get("sourceElementIds"));annotation.putArray("elementIds").add(e.path("id").asText());var response=mapper.createObjectNode();response.set("annotation",annotation);response.putArray("elements").add(e);response.putArray("relations");response.putArray("participants");response.putArray("idMap").addObject().put("clientKey",input.path("clientKey").asText()).put("targetKind","ELEMENT").put("id",e.path("id").asText());var fact=annotation.deepCopy();fact.set("elements",response.get("elements"));fact.putArray("relations");fact.putArray("participants");insert("custom",fact);var index=mapper.createObjectNode();index.putObject("version").set("id",annotation.get("id"));for(String f:List.of("elements","relations","participants"))index.set(f,response.get(f));com.argument.integration.SnapshotObjectOwners.index(jdbc,index,"ARBITER_CUSTOM");receipt(actor,op,key,body,response,i,annotation);return response;}
    @Transactional
    public ObjectNode escalate(Actor actor,String id,String key,int expected,ObjectNode body){validator.validate("J12",body);var s=adjud.locked(actor,id);String op="J12:"+id;var cached=replay(actor,op,key,body);if(cached!=null)return cached;match(s,expected);require("PROPOSITION_REVIEW".equals(s.path("status").asText())&&!"RELATION".equals(body.path("itemKind").asText()),ErrorCode.INVALID_REVIEW_STATE,"本批专家接入限命题阶段");require(!body.path("question").asText().isBlank(),ErrorCode.VALIDATION_ERROR,"请填写专家问题");String expertId=body.path("expertUserId").asText();Actor expert;try{expert=identity.actor(expertId);}catch(BusinessException e){throw new BusinessException(ErrorCode.EXPERT_NOT_ASSIGNED,"所选专家账号当前不可指派");}require(expert.role("EXPERT")&&expert.permission("EXPERT_REVIEW"),ErrorCode.EXPERT_NOT_ASSIGNED,"该账号没有专家权限");var doc=data.read("taskDocument",s.path("taskDocumentId").asText());var members=data.find("member","taskId",doc.path("taskId").asText()).stream().filter(m->expertId.equals(m.path("userId").asText())&&"ACTIVE".equals(m.path("status").asText())&&"EXPERT".equals(m.path("memberRole").asText())).toList();require(members.size()==1,ErrorCode.EXPERT_NOT_ASSIGNED,"专家必须是本任务唯一有效专家成员");ObjectNode item=null;if("GENERAL".equals(body.path("itemKind").asText()))require(body.path("itemId").isNull(),ErrorCode.VALIDATION_ERROR,"一般问题 itemId 必须为 null");else item=item(s,"PROPOSITION",body.path("itemId").asText());if(item!=null)require(Set.of("OPEN","DECIDED").contains(item.path("status").asText()),ErrorCode.INVALID_REVIEW_STATE,"此项已锁定");
        var before=s.deepCopy();var review=mapper.createObjectNode();VersionJson.stamp(review,actor.id(),VersionJson.now());review.put("sessionId",id).put("expertUserId",expertId).put("expertTaskMemberId",members.get(0).path("id").asText()).put("status","REQUESTED").put("requestedById",actor.id()).put("requestedAt",VersionJson.now()).putNull("completedAt");var issue=mapper.createObjectNode();VersionJson.stamp(issue,actor.id(),VersionJson.now());issue.put("expertReviewId",review.path("id").asText()).put("sessionId",id).put("itemKind",body.path("itemKind").asText());issue.set("itemId",body.get("itemId"));issue.put("question",body.path("question").asText().trim()).put("status","OPEN").putNull("resolution").putNull("guideBasis").putNull("resolvedById").putNull("resolvedAt");var resume=mapper.createObjectNode().put("id",review.path("id").asText()).put("sessionId",id).put("phase",s.path("status").asText());if(item!=null){resume.put("itemId",item.path("id").asText());item.put("status","ESCALATED");touch(item,actor);store.saveItem(item);}insert("expertReview",review);insert("expertIssue",issue);insert("expertResume",resume);s.put("status","EXPERT_PENDING").put("currentPhase","EXPERT_PENDING");touch(s,actor);store.saveSession(s);store.transition("J12",actor.id(),body,before,s);var response=mapper.createObjectNode();response.set("review",review);response.putArray("issues").add(issue);response.put("sessionRecordVersion",s.path("recordVersion").asInt());receipt(actor,op,key,body,response,before,s);return response;}
    private ObjectNode assigned(Actor actor,String id){var r=data.read("expertReview",VersionJson.uuid(id));require(actor.role("EXPERT")&&actor.permission("EXPERT_REVIEW")&&actor.id().equals(r.path("expertUserId").asText()),ErrorCode.FORBIDDEN,"只能查看本人专家复核");var s=store.session(r.path("sessionId").asText(),false);var doc=data.read("taskDocument",s.path("taskDocumentId").asText());var m=data.read("member",r.path("expertTaskMemberId").asText());require("ACTIVE".equals(m.path("status").asText())&&"EXPERT".equals(m.path("memberRole").asText())&&actor.id().equals(m.path("userId").asText())&&m.path("taskId").equals(doc.path("taskId")),ErrorCode.FORBIDDEN,"原专家成员已失效");return r;}
    private ObjectNode lockExpert(Actor actor,String id){var r=assigned(actor,id);var s=store.session(r.path("sessionId").asText(),false);versions.lockCase(s.path("taskDocumentId").asText());var doc=data.lock("taskDocument",s.path("taskDocumentId").asText());var task=data.lock("task",doc.path("taskId").asText());store.session(s.path("id").asText(),true);require("IN_PROGRESS".equals(task.path("status").asText())&&"ADJUDICATING".equals(doc.path("status").asText()),ErrorCode.LOCKED_RESOURCE,"任务或案例已锁定");assigned(actor,id);return data.lock("expertReview",id);}
    @Transactional
    public ObjectNode start(Actor actor,String id,String key,int expected,ObjectNode body){validator.validate("X03",body);var r=lockExpert(actor,id);var cached=replay(actor,"X03:"+id,key,body);if(cached!=null)return cached;match(r,expected);require("REQUESTED".equals(r.path("status").asText()),ErrorCode.INVALID_REVIEW_STATE,"复核状态不可接受");var before=r.deepCopy();r.put("status","IN_REVIEW");touch(r,actor);data.replace("expertReview",r);receipt(actor,"X03:"+id,key,body,r,before,r);return r;}
    @Transactional
    public ObjectNode resolve(Actor actor,String id,String key,int expected,ObjectNode body){validator.validate("X04",body);var issue=data.read("expertIssue",VersionJson.uuid(id));var review=lockExpert(actor,issue.path("expertReviewId").asText());issue=data.lock("expertIssue",id);var cached=replay(actor,"X04:"+id,key,body);if(cached!=null)return cached;match(issue,expected);require("IN_REVIEW".equals(review.path("status").asText())&&Set.of("OPEN","RESOLVED").contains(issue.path("status").asText()),ErrorCode.INVALID_REVIEW_STATE,"请先接受复核且不能修改已确认结论");require(!body.path("resolution").asText().isBlank()&&!body.path("guideBasis").asText().isBlank(),ErrorCode.GUIDE_BASIS_REQUIRED,"结论与指南依据均不能为空");var before=issue.deepCopy();issue.put("status","RESOLVED").put("resolution",body.path("resolution").asText().trim()).put("guideBasis",body.path("guideBasis").asText().trim()).put("resolvedById",actor.id()).put("resolvedAt",VersionJson.now());touch(issue,actor);data.replace("expertIssue",issue);receipt(actor,"X04:"+id,key,body,issue,before,issue);return issue;}
    @Transactional
    public ObjectNode confirm(Actor actor,String id,String key,int expected,ObjectNode body){validator.validate("X05",body);var r=lockExpert(actor,id);var cached=replay(actor,"X05:"+id,key,body);if(cached!=null)return cached;match(r,expected);require(body.path("confirmed").asBoolean()&&"IN_REVIEW".equals(r.path("status").asText()),ErrorCode.INVALID_REVIEW_STATE,"请接受复核并确认完成");var issues=data.find("expertIssue","expertReviewId",id);require(!issues.isEmpty()&&issues.stream().allMatch(i->"RESOLVED".equals(i.path("status").asText())&&!i.path("resolution").asText().isBlank()&&!i.path("guideBasis").asText().isBlank()),ErrorCode.OPEN_EXPERT_ISSUES,"所有问题须有结论和指南依据");var s=store.session(r.path("sessionId").asText(),true);require("EXPERT_PENDING".equals(s.path("status").asText()),ErrorCode.INVALID_REVIEW_STATE,"会话已不在专家阶段");var resume=data.read("expertResume",id);require("PROPOSITION_REVIEW".equals(resume.path("phase").asText()),ErrorCode.INVALID_REVIEW_STATE,"回流阶段无效");var before=r.deepCopy();r.put("status","CONFIRMED").put("completedAt",VersionJson.now());touch(r,actor);data.replace("expertReview",r);var beforeSession=s.deepCopy();s.put("status",resume.path("phase").asText()).put("currentPhase",resume.path("phase").asText());if(resume.hasNonNull("itemId")){var i=item(s,"PROPOSITION",resume.path("itemId").asText());require("ESCALATED".equals(i.path("status").asText()),ErrorCode.INVALID_REVIEW_STATE,"专家项已变化");i.put("status","OPEN").putNull("decisionId");touch(i,actor);store.saveItem(i);}touch(s,actor);store.saveSession(s);store.transition("X05",actor.id(),body,beforeSession,s);receipt(actor,"X05:"+id,key,body,r,before,r);return r;}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public ObjectNode detail(Actor actor,String id){var r=assigned(actor,id);return expertDetail(r);}
    private ObjectNode expertDetail(ObjectNode r){var s=store.session(r.path("sessionId").asText(),false);var result=mapper.createObjectNode();result.set("review",r);var snapshots=adjud.snapshots(s);result.set("guideVersionId",snapshots.get(0).path("version").get("guideVersionId"));var issues=result.putArray("issues");var contexts=result.putArray("contexts");for(var issue:data.find("expertIssue","expertReviewId",r.path("id").asText())){issues.add(issue);var ctx=contexts.addObject();ctx.set("issueId",issue.get("id"));ctx.set("itemKind",issue.get("itemKind"));ObjectNode item=issue.hasNonNull("itemId")?item(s,issue.path("itemKind").asText(),issue.path("itemId").asText()):null;if(item==null)ctx.putNull("item");else ctx.set("item",item);var excerpts=ctx.putArray("textExcerpts");var groups=ctx.putArray("candidateGroups");for(var source:snapshots){var g=groups.addObject();g.set("versionId",source.path("version").get("id"));g.set("displayCode",source.path("version").get("displayCode"));var es=g.putArray("elements");g.putArray("relations");g.putArray("participants");for(var e:source.path("elements"))if(item==null||contains(item.path("candidateElementIds"),e.path("id").asText())){es.add(e);var excerpt=excerpts.addObject();for(String f:List.of("documentTextVersionId","annotationScopeId","startOffset","endOffset","text"))excerpt.set(f,e.get(f));}}}return result;}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public ObjectNode list(Actor actor,String status,String q,int page,int size){require(actor.role("EXPERT")&&actor.permission("EXPERT_REVIEW"),ErrorCode.FORBIDDEN,"只有专家可读本人复核列表");require(page>=1&&size>=1&&size<=100&&(status==null||Set.of("REQUESTED","IN_REVIEW","CONFIRMED","RETURNED").contains(status)),ErrorCode.VALIDATION_ERROR,"分页或状态错误");var rows=new ArrayList<ObjectNode>();for(var r:data.find("expertReview","expertUserId",actor.id())){try{assigned(actor,r.path("id").asText());}catch(BusinessException e){if(e.getErrorCode()==ErrorCode.FORBIDDEN)continue;throw e;}if(status!=null&&!status.equals(r.path("status").asText()))continue;var s=store.session(r.path("sessionId").asText(),false);var doc=data.read("taskDocument",s.path("taskDocumentId").asText());var task=data.read("task",doc.path("taskId").asText());var document=data.read("document",doc.path("documentId").asText());if(q!=null&&!task.path("name").asText().contains(q)&&!document.path("title").asText().contains(q))continue;var n=mapper.createObjectNode();n.set("review",r);n.set("taskId",task.get("id"));n.put("taskName",task.path("name").asText());n.set("documentId",doc.get("documentId"));n.put("documentTitle",document.path("title").asText());n.set("guideVersionId",task.get("guideVersionId"));var issues=data.find("expertIssue","expertReviewId",r.path("id").asText());n.put("issueCount",issues.size()).put("openIssueCount",issues.stream().filter(i->!"RESOLVED".equals(i.path("status").asText())).count());rows.add(n);}rows.sort(Comparator.comparing(n->n.path("review").path("createdAt").asText()));var result=mapper.createObjectNode().put("total",rows.size());var items=result.putObject("data").putArray("items");rows.stream().skip((long)(page-1)*size).limit(size).forEach(items::add);return result;}
}
